package in.aicon.pocket;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class LedgerDeviceSyncTest {
 SQLiteDatabase a,b;LedgerSyncStore sa,sb;Cloud cloud=new Cloud();String sub="345678901234567890123";
 static class Cloud implements SyncEngine.Remote {Map<String,SyncEngine.RemoteOperation> operations=new LinkedHashMap<>();int next;
 public List<SyncEngine.RemoteOperation> pull(){return new ArrayList<>(operations.values());}public String reserveFileId(){return "file_"+(++next);}public void append(SyncEngine.Pending p){SyncEngine.RemoteOperation old=operations.get(p.fileId);if(old!=null&&!old.operationId.equals(p.operationId))throw new IllegalStateException();operations.put(p.fileId,new SyncEngine.RemoteOperation(p.fileId,p.operationId,p.record));}public void deleteContentFile(String id){operations.remove(id);}}
 @Before public void setup()throws Exception{Context context=RuntimeEnvironment.getApplication();java.io.File dirA=new java.io.File(context.getCacheDir(),"device-a"),dirB=new java.io.File(context.getCacheDir(),"device-b");dirA.mkdirs();dirB.mkdirs();java.io.File fileA=new java.io.File(dirA,AccountScope.databaseFor(sub)),fileB=new java.io.File(dirB,AccountScope.databaseFor(sub));SQLiteDatabase.deleteDatabase(fileA);SQLiteDatabase.deleteDatabase(fileB);a=SQLiteDatabase.openOrCreateDatabase(fileA,null);b=SQLiteDatabase.openOrCreateDatabase(fileB,null);sa=new LedgerSyncStore(a,sub);sb=new LedgerSyncStore(b,sub);new CatalogStore(a).seed(new String[]{"Food","Home"},new String[]{"Cash","Bank"});}
 @After public void close(){a.close();b.close();}
 void capture(SQLiteDatabase db,LedgerSyncStore store)throws Exception{db.beginTransaction();try{store.captureLocalEdits();db.setTransactionSuccessful();}finally{db.endTransaction();}}
 void sync(LedgerSyncStore store)throws Exception{new SyncEngine(store,cloud,()->{},records->LedgerWire.validate(records)).sync();}
 void insert(SQLiteDatabase db,JSONObject j)throws Exception{ContentValues v=new ContentValues();Iterator<String> keys=j.keys();while(keys.hasNext()){String k=keys.next();if(k.equals("type"))continue;Object value=j.get(k);if(value instanceof Number)v.put(k,((Number)value).longValue());else v.put(k,value.toString());}db.insertOrThrow("tx",null,v);}
 String text(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){assertTrue(c.moveToFirst());return c.getString(0);}}
 @Test public void twoDevicesKeepOfflineRepaymentLinkedAcrossAccountAndPersonRenames()throws Exception{
  String loan=UUID.randomUUID().toString();insert(a,LedgerWire.transaction(loan,"lent",50000,"2026-11-11","Cash","","Debt","","Sample",""));capture(a,sa);sync(sa);sync(sb);assertEquals("50000",text(b,"SELECT amount FROM tx"));CatalogStore cb=new CatalogStore(b);CatalogStore.Item account=cb.find("account","Cash"),person=cb.find("person","Sample");cb.put(account.id,"account","Daily funds",22,"Rose");cb.put(person.id,"person","Renamed sample",16,"Violet");capture(b,sb);sync(sb);
  String payment=UUID.randomUUID().toString();insert(a,LedgerWire.transaction(payment,"repay_in",20000,"2026-11-11","Cash","","Debt","","Sample",loan));capture(a,sa);sync(sa);sync(sb);assertEquals("2",text(b,"SELECT count(*) FROM tx"));assertEquals("2",text(a,"SELECT count(*) FROM tx WHERE account='Daily funds' AND person='Renamed sample'"));assertEquals(loan,text(b,"SELECT loan FROM tx WHERE kind='repay_in'"));assertEquals("Rose",new CatalogStore(a).find("account","Daily funds").color);
  a.beginTransaction();try{a.delete("tx","loan=? OR uuid=?",new String[]{loan,loan});sa.captureLocalEdits();a.setTransactionSuccessful();}finally{a.endTransaction();}sync(sa);sync(sb);assertEquals("0",text(b,"SELECT count(*) FROM tx"));for(SyncEngine.RemoteOperation op:cloud.operations.values())if(op.record.id.equals(loan)||op.record.id.equals(payment)){assertTrue(op.record.deleted);assertNull(op.record.payload);}
 }
 @Test public void localCurrencyRelabelAttemptRollsBackPreferencesAndOutbox()throws Exception{insert(a,LedgerWire.transaction(UUID.randomUUID().toString(),"income",50000,"2026-11-11","Cash","","Food","","",""));capture(a,sa);long revision=sa.snapshot().revision;int pending=sa.pending().size();a.beginTransaction();try{new SettingsStore(a).put("currency","USD");try{sa.captureLocalEdits();fail();}catch(IllegalArgumentException expected){}}finally{a.endTransaction();}assertEquals("INR",new SettingsStore(a).get("currency"));assertEquals(revision,sa.snapshot().revision);assertEquals(pending,sa.pending().size());}
}
